import sys, re, os
from datetime import datetime

MONTHS = {m: i+1 for i, m in enumerate(
    "january february march april may june july august september october november december".split())}
MONTHS_ABBR = {m[:3]: i+1 for m, i in MONTHS.items()}
ALL_MONTHS = {**MONTHS, **MONTHS_ABBR}

def parse_date_header(line):
    line = line.strip()
    m = re.match(r'^([A-Za-z]+)\s+(\d{1,2})\s+(\d{4})\s+([A-Za-z]+)$', line)
    if m:
        mon = ALL_MONTHS.get(m.group(1).lower())
        if mon:
            return datetime(int(m.group(3)), mon, int(m.group(2))), m.group(4)
    m = re.match(r'^(\d{1,2})\s+([A-Za-z]+)\s+(\d{4})\s+([A-Za-z]+)$', line)
    if m:
        mon = ALL_MONTHS.get(m.group(2).lower())
        if mon:
            return datetime(int(m.group(3)), mon, int(m.group(1))), m.group(4)
    return None, None

def norm_time(t):
    t = t.replace('.', ':')
    if t.count(':') == 1:
        t += ':00'
    return t

def parse_entries(lines):
    current_date = None
    current_day_name = None
    entries = []
    in_brace = False
    brace_outer = None
    brace_notes = []

    for line in lines:
        s = line.strip()
        if not s or re.match(r'^[=\-]{3,}$', s):
            continue

        dt, dn = parse_date_header(s)
        if dt:
            current_date, current_day_name = dt, dn
            continue

        has_open = '{' in s
        has_close = '}' in s
        clean = s.replace('{', '').replace('}', '').strip()

        m = re.match(
            r'(\d{1,2}[:.]\d{2}(?::\d{2})?)\s*(?:to|–|-)\s*'
            r'(\d{1,2}[:.]\d{2}(?::\d{2})?)\s*'
            r'"(.+)"',
            clean
        )

        if m:
            start = norm_time(m.group(1))
            end = norm_time(m.group(2))
            desc = m.group(3)
            entry = {'date': current_date, 'day': current_day_name,
                     'start': start, 'end': end, 'desc': desc}

            if has_open:
                in_brace = True
                brace_outer = entry
                brace_notes = []
            elif in_brace:
                if brace_notes:
                    entry['desc'] += ' (' + '; '.join(brace_notes) + ')'
                    brace_notes = []
                entries.append(entry)
                if has_close:
                    in_brace = False
            else:
                entries.append(entry)
                if has_close:
                    pass
        else:
            nm = re.match(r'^"(.+)"$', clean)
            if nm and in_brace:
                brace_notes.append(nm.group(1))
            if has_close and in_brace:
                if brace_outer:
                    if brace_notes:
                        brace_outer['desc'] += ' (' + '; '.join(brace_notes) + ')'
                    entries.append(brace_outer)
                elif brace_notes:
                    entries.append({'date': current_date, 'day': current_day_name,
                                    'start': '00:00:00', 'end': '00:00:00',
                                    'desc': '; '.join(brace_notes)})
                in_brace = False
                brace_outer = None
                brace_notes = []

    entries.sort(key=lambda e: (e['date'], e['start']))
    return entries

def main():
    if len(sys.argv) < 2:
        print("usage: python3 convert_work_log.py <input> [output]")
        sys.exit(1)
    with open(sys.argv[1]) as f:
        lines = f.readlines()
    entries = parse_entries(lines)
    out_path = sys.argv[2] if len(sys.argv) > 2 else None
    out = open(out_path, 'w') if out_path else sys.stdout
    for e in entries:
        ds = e['date'].strftime("%d/%m/%Y")
        out.write(f'{ds} {e["day"]} {e["start"]} {e["end"]} "{e["desc"]}"\n')
    if out_path:
        out.close()
        print(f"wrote {len(entries)} entries to {out_path}")

if __name__ == '__main__':
    main()
