import sys

def main():
    with open(sys.argv[1]) as f:
        lines = f.readlines()

    out_lines = []
    i = 0
    while i < len(lines):
        raw = lines[i]
        s = raw.rstrip()
        idx = s.find('[')
        if idx >= 0 and not s[:idx].strip():
            depth = 0
            j = i
            closed = False
            for j in range(i, len(lines)):
                for ch in lines[j]:
                    if ch == '[':
                        depth += 1
                    elif ch == ']':
                        depth -= 1
                        if depth == 0:
                            closed = True
                            break
                if closed:
                    break
            if closed:
                i = j + 1
                continue
        out_lines.append(raw)
        i += 1

    with open(sys.argv[2], 'w') as f:
        f.writelines(out_lines)

    print(f"wrote {len(out_lines)} lines to {sys.argv[2]}")

if __name__ == '__main__':
    main()

